mapper.select:
SELECT SM.SALES_NO , SM.SALES_SEQ , SM.INVOICE_MONTH , D.DIVISION_NAME , C.CUSTOMER_NAME , SM.PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , IM.HS_CODE , COALESCE(SM.STATUS, 0) AS STATUS , GET_CODE_NAME(COALESCE(SM.STATUS, 0)::VARCHAR, 'DS', SM.COMPANY_CODE, 'KOR') AS STATUS_NAME , GET_CODE_NAME(SM.PRODUCT_ASSETS_TYPE, 'AT', SM.COMPANY_CODE, 'KOR') AS PRODUCT_ASSETS_TYPE_NAME , SM.COO_CERTIFY_NO FROM (
SELECT SM.COMPANY_CODE , SM.SALES_NO , SD.SALES_SEQ , SUBSTR(SM.INVOICE_DATE, 1, 6) AS INVOICE_MONTH , SD.DIVISION_CODE , SM.CUSTOMER_CODE , SD.PRODUCT_CODE , SD.QUANTITY , SD.PRODUCT_ASSETS_TYPE , (SELECT SD2.STATUS::INTEGER FROM SALES_MST SM2 INNER JOIN SALES_DTL SD2 ON SM2.COMPANY_CODE = SD2.COMPANY_CODE AND SM2.SALES_NO = SD2.SALES_NO AND SM2.DIVISION_CODE = SD2.DIVISION_CODE WHERE SM2.COMPANY_CODE = SM.COMPANY_CODE AND SM2.VIRTUAL_YN = 'Y' AND SM2.CUSTOMER_CODE = SM.CUSTOMER_CODE AND SD2.DIVISION_CODE = SD.DIVISION_CODE AND SD2.PRODUCT_CODE = SD.PRODUCT_CODE AND SUBSTR(SM2.INVOICE_DATE, 1, 6) = SUBSTR(SM.INVOICE_DATE, 1, 6) FETCH FIRST 1 ROW ONLY) AS STATUS , (SELECT SD2.COO_CERTIFY_NO FROM SALES_MST SM2 INNER JOIN SALES_DTL SD2 ON SM2.COMPANY_CODE = SD2.COMPANY_CODE AND SM2.SALES_NO = SD2.SALES_NO AND SM2.DIVISION_CODE = SD2.DIVISION_CODE WHERE SM2.COMPANY_CODE = SM.COMPANY_CODE AND SM2.VIRTUAL_YN = 'Y' AND SM2.CUSTOMER_CODE = SM.CUSTOMER_CODE AND SD2.DIVISION_CODE = SD.DIVISION_CODE AND SD2.PRODUCT_CODE = SD.PRODUCT_CODE AND SUBSTR(SM2.INVOICE_DATE, 1, 6) = SUBSTR(SM.INVOICE_DATE, 1, 6) FETCH FIRST 1 ROW ONLY) AS COO_CERTIFY_NO FROM SALES_MST SM INNER JOIN SALES_DTL SD ON SM.COMPANY_CODE = SD.COMPANY_CODE AND SM.SALES_NO = SD.SALES_NO AND SM.DIVISION_CODE = SD.DIVISION_CODE INNER JOIN CUSTOMER DC ON DC.COMPANY_CODE = SD.COMPANY_CODE AND DC.CUSTOMER_CODE = SD.DELIVERY_CUSTOMER_CODE WHERE SM.COMPANY_CODE = #{company_code} AND SM.EXPORT_FLAG = 'D' AND SM.VIRTUAL_YN = 'N'
AND SM.INVOICE_DATE BETWEEN #{from_date} AND #{to_date}
) SM INNER JOIN ITEM_MST IM ON IM.COMPANY_CODE = SM.COMPANY_CODE AND IM.ITEM_CODE = SM.PRODUCT_CODE LEFT JOIN DIVISION D ON D.COMPANY_CODE = SM.COMPANY_CODE AND D.DIVISION_CODE = SM.DIVISION_CODE INNER JOIN CUSTOMER C ON C.COMPANY_CODE = SM.COMPANY_CODE AND C.CUSTOMER_CODE = SM.CUSTOMER_CODE WHERE 1=1 AND SM.QUANTITY > 0 -- 반품 제외
AND D.DIVISION_CODE = #{division_code}
AND (C.CUSTOMER_CODE ILIKE '%' || #{customer} || '%' OR C.CUSTOMER_NAME ILIKE '%' || #{customer} || '%' )
AND (SM.PRODUCT_CODE ILIKE '%' || #{product} || '%' OR IM.ITEM_NAME ILIKE '%' || #{product} || '%' )
ORDER BY SM.INVOICE_MONTH, C.CUSTOMER_CODE, D.DIVISION_CODE, SM.PRODUCT_CODE, SM.SALES_NO, SM.SALES_SEQ
